// Provider management for the app's native screen.
//
// The provider list used to be a JSON window generated by the provider-ui
// extension. The app now renders it with Compose and edits the same file the
// extension writes (`~/.pig/agent/custom-endpoints.json`); the relay is the
// file server and also fetches `/models` so the user can pick which models a
// provider exposes before saving.
//
// A provider is applied by restarting pig: the custom-endpoints extension reads
// this file at session start and registers whatever is in it. That keeps one
// writer (this file) instead of two, and a failed fetch can never leave the
// running session believing in models that were never stored.
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"sync"
	"time"
)

const (
	providerFetchTimeout = 20 * time.Second
	providerResolveLimit = 10 * time.Second
)

var (
	providerIDPattern = regexp.MustCompile(`^[a-z0-9][a-z0-9._-]{0,31}$`)
	providerEnvRef    = regexp.MustCompile(`\$\{([A-Za-z_][A-Za-z0-9_]*)\}|\$([A-Za-z_][A-Za-z0-9_]*)`)
	// Top-level keys in the provider store that are not provider ids.
	providerReserved = map[string]bool{"defaults": true, "providers": true, "$schema": true}
	// API spellings the custom-endpoints extension understands.
	providerAPIs = map[string]bool{
		"openai-completions":      true,
		"openai-responses":        true,
		"anthropic-messages":      true,
		"google-generative-ai":    true,
		"google-vertex":           true,
		"mistral-conversations":   true,
		"azure-openai-responses":  true,
		"openai-codex-responses":  true,
		"bedrock-converse-stream": true,
	}
)

// providerWriteMu keeps two saves/deletes from interleaving their read-modify-
// write cycle on custom-endpoints.json.
var providerWriteMu sync.Mutex

func (s *session) providerPaths() (config, cache, models string) {
	agentDir := filepath.Dir(s.settingsPath)
	return filepath.Join(agentDir, "custom-endpoints.json"),
		filepath.Join(agentDir, "custom-endpoints.cache.json"),
		filepath.Join(agentDir, "models.json")
}

// sendProviders lists the custom providers plus the ids models.json owns.
func (s *session) sendProviders(id any) {
	configPath, cachePath, modelsPath := s.providerPaths()
	store, err := readJSONObjectFile(configPath)
	if err != nil {
		_ = s.send(frame{"type": "relay_provider_error", "id": id, "op": "list", "message": err.Error()})
		return
	}
	providers := providerMapOf(store)
	cache, _ := readJSONObjectFile(cachePath)
	modelsStore, _ := readJSONObjectFile(modelsPath)
	modelsProviders := make([]string, 0)
	if list, ok := modelsStore["providers"].(map[string]any); ok {
		for key := range list {
			modelsProviders = append(modelsProviders, key)
		}
		sort.Strings(modelsProviders)
	}

	ids := make([]string, 0, len(providers))
	for pid := range providers {
		ids = append(ids, pid)
	}
	sort.Strings(ids)
	views := make([]any, 0, len(ids))
	for _, pid := range ids {
		def, _ := providers[pid].(map[string]any)
		if def == nil {
			continue
		}
		views = append(views, providerView(pid, def, cache))
	}
	_ = s.send(frame{
		"type":            "relay_providers",
		"id":              id,
		"path":            configPath,
		"providers":       views,
		"modelsProviders": modelsProviders,
		"offline":         providerOffline(),
	})
}

func providerView(pid string, def, cache map[string]any) frame {
	auto := providerAuto(def)
	var models []any
	var cachedModels []any
	var fetchedAt int64
	if cached, ok := cache[pid].(map[string]any); ok {
		if list, ok := cached["models"].([]any); ok {
			cachedModels = sanitizeModels(list)
		}
		switch value := cached["fetchedAt"].(type) {
		case float64:
			fetchedAt = int64(value)
		case json.Number:
			if number, err := value.Int64(); err == nil {
				fetchedAt = number
			}
		}
	}
	if !auto {
		if list, ok := def["models"].([]any); ok {
			models = sanitizeModels(list)
		} else {
			models = []any{}
		}
	} else {
		models = cachedModels
	}
	if models == nil {
		models = []any{}
	}
	if cachedModels == nil {
		cachedModels = []any{}
	}
	name := providerString(def, "name")
	if name == "" {
		name = pid
	}
	return frame{
		"id":           pid,
		"name":         name,
		"baseUrl":      providerString(def, "baseUrl"),
		"api":          providerString(def, "api"),
		"hasKey":       providerString(def, "apiKey") != "",
		"auto":         auto,
		"modelsUrl":    providerString(def, "modelsUrl"),
		"models":       models,
		"cachedModels": cachedModels,
		"fetchedAt":    fetchedAt,
	}
}

// saveProvider writes one provider, preserving keys the app does not edit
// (headers, oauth, fetchModels, refresh options, defaults...).
func (s *session) saveProvider(id any, entry map[string]any) {
	providerWriteMu.Lock()
	defer providerWriteMu.Unlock()
	fail := func(message string) {
		_ = s.send(frame{"type": "relay_provider_error", "id": id, "op": "save", "message": message})
	}
	if entry == nil {
		fail("缺少供应商数据")
		return
	}
	pid := strings.ToLower(providerString(entry, "id"))
	if !providerIDPattern.MatchString(pid) {
		fail("ID 只能是小写字母、数字、点、下划线和短横线（1–32 个字符）")
		return
	}
	baseURL := strings.TrimRight(providerString(entry, "baseUrl"), "/")
	parsed, err := url.Parse(baseURL)
	if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") || parsed.Host == "" {
		fail("Base URL 必须是 http(s) 地址，例如 https://api.example.com/v1")
		return
	}
	api := providerString(entry, "api")
	if api == "" {
		api = "openai-completions"
	}
	if !providerAPIs[api] {
		fail("不支持的 API 类型: " + api)
		return
	}
	auto, hasAuto := entry["auto"].(bool)
	if !hasAuto {
		auto = true
	}
	selected := sanitizeModels(entryModels(entry, "models"))
	full := sanitizeModels(entryModels(entry, "cacheModels"))
	if !auto && len(selected) == 0 {
		fail("关闭「自动获取全部模型」后，至少要选择一个模型")
		return
	}

	configPath, cachePath, _ := s.providerPaths()
	store, err := readJSONObjectFile(configPath)
	if err != nil {
		fail("读取 custom-endpoints.json 失败: " + err.Error())
		return
	}
	providers := providerMapOf(store)
	old, _ := providers[pid].(map[string]any)
	def := map[string]any{}
	for key, value := range old {
		def[key] = value
	}
	name := providerString(entry, "name")
	if name == "" {
		name = pid
	}
	def["name"] = name
	def["baseUrl"] = baseURL
	def["api"] = api
	if clear, _ := entry["clearKey"].(bool); clear {
		delete(def, "apiKey")
	} else if key := providerString(entry, "apiKey"); key != "" {
		// A blank key means "keep the stored one": the app never receives the
		// secret back, so it cannot round-trip it.
		def["apiKey"] = key
	}
	modelsURL := strings.TrimRight(providerString(entry, "modelsUrl"), "/")
	if auto {
		def["models"] = "auto"
		// Keep the endpoint-derived auto marker; clear the two flags that would
		// contradict an explicit models array from an older save.
		delete(def, "fetchModels")
		if modelsURL == "" {
			delete(def, "modelsUrl")
		} else {
			def["modelsUrl"] = modelsURL
		}
	} else {
		def["models"] = selected
		// A modelsUrl makes the extension fetch and ignore this array (its
		// auto() treats the key as "auto"). Manual selection must be manual.
		delete(def, "fetchModels")
		delete(def, "modelsUrl")
	}
	providers[pid] = def
	if err := writeJSONAtomic(configPath, store); err != nil {
		fail("写入 custom-endpoints.json 失败: " + err.Error())
		return
	}

	cache, _ := readJSONObjectFile(cachePath)
	warning := ""
	// The app refreshes a draft before saving. That fetch can fail (slow
	// endpoint, a key typed after the click, a transient 5xx) while the
	// extension's fetch after the restart succeeds - which is why models
	// "appear later". If auto mode has no list to cache yet, fetch here so the
	// save itself is the retry; on failure still save and say what will happen.
	if auto && len(full) == 0 && len(selected) == 0 {
		existing := []any{}
		if cached, ok := cache[pid].(map[string]any); ok {
			existing, _ = cached["models"].([]any)
		}
		if len(existing) == 0 {
			switch {
			case providerOffline():
				warning = "已保存；离线模式，联网后会自动获取模型列表"
			default:
				if fetched, err := fetchProviderModels(def); err != nil {
					warning = "已保存；模型列表获取失败（" + err.Error() + "），pig 启动时会再试"
				} else {
					full = sanitizeModels(fetched)
				}
			}
		}
	}
	// Keep the full fetched list even when the user enabled a subset: the
	// picker needs it the next time this provider is edited, and switching
	// back to "all models" must not need another network round trip.
	cachedList := full
	if len(cachedList) == 0 {
		cachedList = selected
	}
	if len(cachedList) > 0 {
		cache[pid] = map[string]any{
			"fetchedAt": time.Now().UnixMilli(),
			"models":    cachedList,
		}
		if err := writeJSONAtomic(cachePath, cache); err != nil {
			// The provider itself is saved; only the cached list failed. Tell
			// the app so it can retry the refresh.
			_ = s.send(frame{
				"type":     "relay_provider_saved",
				"id":       id,
				"op":       "save",
				"provider": providerView(pid, def, cache),
				"warning":  "已保存，但模型缓存写入失败: " + err.Error(),
			})
			return
		}
	}
	done := frame{
		"type":     "relay_provider_saved",
		"id":       id,
		"op":       "save",
		"provider": providerView(pid, def, cache),
		"path":     configPath,
	}
	if warning != "" {
		done["warning"] = warning
	}
	_ = s.send(done)
}

func (s *session) deleteProvider(id any, entry map[string]any) {
	providerWriteMu.Lock()
	defer providerWriteMu.Unlock()
	fail := func(message string) {
		_ = s.send(frame{"type": "relay_provider_error", "id": id, "op": "delete", "message": message})
	}
	pid := strings.ToLower(providerString(entry, "id"))
	if pid == "" {
		fail("缺少供应商 ID")
		return
	}
	configPath, cachePath, modelsPath := s.providerPaths()
	store, err := readJSONObjectFile(configPath)
	if err != nil {
		fail("读取 custom-endpoints.json 失败: " + err.Error())
		return
	}
	providers := providerMapOf(store)
	if _, ok := providers[pid]; !ok {
		hint := ""
		if modelsStore, err := readJSONObjectFile(modelsPath); err == nil {
			if list, ok := modelsStore["providers"].(map[string]any); ok {
				if _, exists := list[pid]; exists {
					hint = "（它在 models.json 里，这里不修改 models.json）"
				}
			}
		}
		fail(fmt.Sprintf("没有自定义供应商 %q%s", pid, hint))
		return
	}
	delete(providers, pid)
	if err := writeJSONAtomic(configPath, store); err != nil {
		fail("写入 custom-endpoints.json 失败: " + err.Error())
		return
	}
	cache, _ := readJSONObjectFile(cachePath)
	delete(cache, pid)
	_ = writeJSONAtomic(cachePath, cache)
	_ = s.send(frame{"type": "relay_provider_deleted", "id": id, "op": "delete", "provider": pid})
}

// sendProviderModels fetches a draft provider's model list without saving it.
func (s *session) sendProviderModels(id any, entry map[string]any) {
	fail := func(message string) {
		_ = s.send(frame{"type": "relay_provider_error", "id": id, "op": "refresh", "message": message})
	}
	if providerOffline() {
		fail("离线模式下无法刷新模型列表")
		return
	}
	pid := strings.ToLower(providerString(entry, "id"))
	baseURL := strings.TrimRight(providerString(entry, "baseUrl"), "/")
	if baseURL == "" {
		fail("Base URL 必填")
		return
	}
	configPath, _, _ := s.providerPaths()
	store, _ := readJSONObjectFile(configPath)
	stored, _ := providerMapOf(store)[pid].(map[string]any)
	def := map[string]any{}
	for key, value := range stored {
		def[key] = value
	}
	def["baseUrl"] = baseURL
	if api := providerString(entry, "api"); api != "" {
		def["api"] = api
	}
	if key := providerString(entry, "apiKey"); key != "" {
		def["apiKey"] = key
	}
	if modelsURL := providerString(entry, "modelsUrl"); modelsURL != "" {
		def["modelsUrl"] = modelsURL
	}
	models, err := fetchProviderModels(def)
	if err != nil {
		fail(err.Error())
		return
	}
	_ = s.send(frame{
		"type":      "relay_provider_models",
		"id":        id,
		"op":        "refresh",
		"provider":  pid,
		"models":    models,
		"fetchedAt": time.Now().UnixMilli(),
	})
}

// providerSecretQuery matches API keys carried in a query string. Errors and
// status messages interpolate the request URL, and those strings go straight
// to the app's provider screen and into exported logs.
var providerSecretQuery = regexp.MustCompile(`(?i)([?&](?:key|api_key|api-key|token|access_token)=)[^&\s"]+`)

func redactProviderText(text string) string {
	return providerSecretQuery.ReplaceAllString(text, "$1***")
}

// fetchProviderModels asks the endpoint for its model list, mirroring the
// provider-ui extension's headers/api-key rules.
func fetchProviderModels(def map[string]any) ([]any, error) {
	base := strings.TrimRight(providerString(def, "baseUrl"), "/")
	if base == "" {
		return nil, fmt.Errorf("baseUrl 为空")
	}
	requestURL := providerString(def, "modelsUrl")
	if requestURL == "" {
		requestURL = base + "/models"
	}
	api := providerString(def, "api")
	key := expandProviderValue(providerString(def, "apiKey"))

	headers := map[string]string{}
	for _, field := range []string{"headers", "modelsHeaders"} {
		raw, _ := def[field].(map[string]any)
		for name, value := range raw {
			if text, ok := value.(string); ok {
				headers[name] = expandProviderValue(text)
			}
		}
	}
	if key != "" && !providerHasHeader(headers, "authorization") && !providerHasHeader(headers, "x-api-key") {
		switch {
		case api == "anthropic-messages":
			headers["x-api-key"] = key
			if !providerHasHeader(headers, "anthropic-version") {
				headers["anthropic-version"] = "2023-06-01"
			}
		case strings.HasPrefix(api, "google"):
			separator := "?"
			if strings.Contains(requestURL, "?") {
				separator = "&"
			}
			requestURL += separator + "key=" + url.QueryEscape(key)
		default:
			headers["Authorization"] = "Bearer " + key
		}
	}
	client := providerHTTPClient()
	request, err := http.NewRequest(http.MethodGet, requestURL, nil)
	if err != nil {
		return nil, err
	}
	for name, value := range headers {
		request.Header.Set(name, value)
	}
	response, err := client.Do(request)
	if err != nil {
		// url.Error wraps the full URL, including `?key=...`.
		return nil, fmt.Errorf("%s", redactProviderText(err.Error()))
	}
	defer response.Body.Close()
	if response.StatusCode < 200 || response.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(response.Body, 512))
		message := strings.TrimSpace(string(body))
		if message != "" {
			return nil, fmt.Errorf("%s", redactProviderText(
				fmt.Sprintf("%s -> HTTP %d: %s", requestURL, response.StatusCode, message)))
		}
		return nil, fmt.Errorf("%s", redactProviderText(
			fmt.Sprintf("%s -> HTTP %d %s", requestURL, response.StatusCode, response.Status)))
	}
	var payload any
	if err := json.NewDecoder(io.LimitReader(response.Body, 8<<20)).Decode(&payload); err != nil {
		return nil, err
	}
	list := providerExtractModels(payload)
	if len(list) == 0 {
		return nil, fmt.Errorf("%s 未返回任何模型", redactProviderText(requestURL))
	}
	models := make([]any, 0, len(list))
	for _, raw := range list {
		if model, ok := providerNormalizeModel(raw); ok {
			models = append(models, model)
		}
	}
	if len(models) == 0 {
		return nil, fmt.Errorf("%s 未返回可识别的模型", requestURL)
	}
	sort.SliceStable(models, func(i, j int) bool {
		return providerString(models[i].(map[string]any), "id") <
			providerString(models[j].(map[string]any), "id")
	})
	return models, nil
}

func providerExtractModels(payload any) []any {
	switch value := payload.(type) {
	case []any:
		return value
	case map[string]any:
		for _, key := range []string{"data", "models", "items", "result"} {
			if list, ok := value[key].([]any); ok {
				return list
			}
		}
	}
	return nil
}

// providerNormalizeModel accepts both an endpoint listing entry and a model
// object the app already normalized (contextWindow/maxTokens), so a round trip
// through save never loses those values.
func providerNormalizeModel(raw any) (map[string]any, bool) {
	object, ok := raw.(map[string]any)
	if !ok {
		if text, ok := raw.(string); ok && strings.TrimSpace(text) != "" {
			return map[string]any{"id": text, "name": text}, true
		}
		return nil, false
	}
	id := providerFirstString(object, "id", "name", "model")
	id = strings.TrimPrefix(id, "models/")
	if id == "" {
		return nil, false
	}
	name := providerFirstString(object, "displayName", "name")
	name = strings.TrimPrefix(name, "models/")
	if name == "" || name == id {
		name = id
	}
	model := map[string]any{"id": id, "name": name}
	if window := providerFirstNumber(object, "contextWindow", "context_length", "context_window", "max_model_len", "inputTokenLimit"); window > 0 {
		model["contextWindow"] = int64(window)
	}
	if max := providerFirstNumber(object, "maxTokens", "max_tokens", "max_output_tokens", "outputTokenLimit"); max > 0 {
		model["maxTokens"] = int64(max)
	}
	if reasoning, ok := object["reasoning"].(bool); ok {
		model["reasoning"] = reasoning
	}
	if input, ok := object["input"].([]any); ok {
		model["input"] = input
	}
	if vision, ok := object["supports_vision"].(bool); ok && vision {
		model["input"] = []any{"text", "image"}
	}
	return model, true
}

func providerFirstString(object map[string]any, keys ...string) string {
	for _, key := range keys {
		if value, ok := object[key].(string); ok && strings.TrimSpace(value) != "" {
			return strings.TrimSpace(value)
		}
	}
	return ""
}

func providerFirstNumber(object map[string]any, keys ...string) float64 {
	for _, key := range keys {
		switch value := object[key].(type) {
		case float64:
			if value > 0 {
				return value
			}
		case json.Number:
			if number, err := value.Float64(); err == nil && number > 0 {
				return number
			}
		}
	}
	return 0
}

func providerHasHeader(headers map[string]string, name string) bool {
	for key := range headers {
		if strings.EqualFold(key, name) {
			return true
		}
	}
	return false
}

// expandProviderValue expands `$ENV`, `${ENV}` and `!command` like the
// extension does, so a key stored as `$MY_KEY` still works.
func expandProviderValue(raw string) string {
	if raw == "" {
		return ""
	}
	if strings.HasPrefix(raw, "!") {
		return providerRunShell(raw[1:])
	}
	const dollar = "\x00D\x00"
	const bang = "\x00B\x00"
	value := strings.ReplaceAll(raw, "$$", dollar)
	value = strings.ReplaceAll(value, "$!", bang)
	value = providerEnvRef.ReplaceAllStringFunc(value, func(match string) string {
		return os.Getenv(strings.Trim(match, "${}"))
	})
	value = strings.ReplaceAll(value, dollar, "$")
	return strings.ReplaceAll(value, bang, "!")
}

func providerRunShell(command string) string {
	// CommandContext kills the shell (and waits for it) when the limit is hit;
	// the old timer returned "" but left the child and its own children alive.
	ctx, cancel := context.WithTimeout(context.Background(), providerResolveLimit)
	defer cancel()
	out, err := exec.CommandContext(ctx, "sh", "-c", command).Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

func providerOffline() bool {
	value := strings.TrimSpace(os.Getenv("PIG_OFFLINE"))
	if value == "" {
		value = strings.TrimSpace(os.Getenv("PI_OFFLINE"))
	}
	switch strings.ToLower(value) {
	case "1", "true", "yes":
		return true
	}
	return false
}

// ---- provider store -------------------------------------------------------

func providerMapOf(store map[string]any) map[string]any {
	if nested, ok := store["providers"].(map[string]any); ok {
		return nested
	}
	nested := map[string]any{}
	for key, value := range store {
		if providerReserved[key] {
			continue
		}
		nested[key] = value
		delete(store, key)
	}
	store["providers"] = nested
	return nested
}

func providerAuto(def map[string]any) bool {
	if marker, ok := def["models"].(string); ok && marker == "auto" {
		return true
	}
	if flag, ok := def["fetchModels"].(bool); ok && flag {
		return true
	}
	if marker, ok := def["fetchModels"].(string); ok && marker == "auto" {
		return true
	}
	return providerString(def, "modelsUrl") != ""
}

// sanitizeModels keeps the fields the session needs and drops anything else a
// malformed request might carry.
func sanitizeModels(list []any) []any {
	out := make([]any, 0, len(list))
	for _, raw := range list {
		model, ok := providerNormalizeModel(raw)
		if !ok {
			continue
		}
		out = append(out, model)
	}
	return out
}

func entryModels(entry map[string]any, key string) []any {
	if list, ok := entry[key].([]any); ok {
		return list
	}
	return nil
}

func providerString(object map[string]any, key string) string {
	value, _ := object[key].(string)
	return strings.TrimSpace(value)
}

// readJSONObjectFile reads a JSON object; a missing file is an empty object.
func readJSONObjectFile(path string) (map[string]any, error) {
	store := map[string]any{}
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return store, nil
		}
		return store, err
	}
	if len(strings.TrimSpace(string(data))) == 0 {
		return store, nil
	}
	if err := json.Unmarshal(data, &store); err != nil {
		return map[string]any{}, fmt.Errorf("%s: %w", filepath.Base(path), err)
	}
	if store == nil {
		store = map[string]any{}
	}
	return store, nil
}

// writeJSONAtomic writes an owner-only JSON file and keeps the previous copy.
func writeJSONAtomic(path string, value map[string]any) error {
	data, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return err
	}
	if old, err := os.ReadFile(path); err == nil {
		backup := path + ".bak-" + time.Now().Format("20060102-150405") + "-pre-app"
		// A backup failure must not block the edit; the atomic rename below
		// still leaves either the old or the new file.
		_ = os.WriteFile(backup, old, 0o600)
	}
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".tmp*")
	if err != nil {
		return err
	}
	name := tmp.Name()
	defer os.Remove(name)
	if _, err := tmp.Write(append(data, '\n')); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(name, 0o600); err != nil {
		return err
	}
	return os.Rename(name, path)
}
